# Pseudocode — TenthMatrix example (not TypeSafe sample verbatim)
response = system_one.ask(
  state={"alert": alert_text, "service": svc, "last_deploys": deploys},
  questions={
    "area": Choice({
      "capacity": "Resource saturation or quota",
      "dependency": "Upstream/downstream failure",
      "regression": "Likely bad deploy/code",
      "config": "Flag, secret, or env drift",
      "unknown": "Insufficient evidence",
    })
  }
)
if response.confidence("area") < 0.7:
  escalate(response)
else:
  route(response.best("area"))
